INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Hashfunktionen nur für Passwörter wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Sie sichern auch andere Daten"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Hashfunktionen?', 3, '[{"text": "Integritätssicherung", "correct": true, "because": "Überprüft Datenkorrektheit"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Sicherheit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften haben Hashfunktionen?', 5, '[{"text": "Einwegfunktion", "correct": true, "because": "Nicht umkehrbar"}, {"text": "Kollisionsresistenz", "correct": true, "because": "Einzigartige Hashwerte"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SHA-256 sichert Integrität. b) Es verschlüsselt Daten direkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verschlüsselung ist separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von Hashfunktionen?', 4, '[{"text": "Algorithmuswahl", "correct": false, "because": "Bestimmt Sicherheit"}, {"text": "Salt bei Passwörtern", "correct": false, "because": "Erhöht Schutz"}, {"text": "Grafisches Design", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Hashfunktionen umkehrbar sind?', 2, '[{"text": "Nein", "correct": true, "because": "Einwegfunktion"}, {"text": "Ja", "correct": false, "because": "Nicht umkehrbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hashfunktion ist weit verbreitet?', 3, '[{"text": "SHA-256", "correct": true, "because": "Stark und sicher"}, {"text": "MD5", "correct": false, "because": "Veraltet und unsicher"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Algorithmus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen nutzen Hashfunktionen?', 5, '[{"text": "Passwort-Speicherung", "correct": true, "because": "Sichert Zugangsdaten"}, {"text": "Dateiintegrität", "correct": true, "because": "Prüft Veränderungen"}, {"text": "Datenbankgröße", "correct": false, "because": "Irrelevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Hashfunktionen schützen Integrität. b) Sie sind leicht umkehrbar. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht umkehrbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Hashfunktionen?', 4, '[{"text": "Starker Algorithmus", "correct": false, "because": "Sicherheit gewährleisten"}, {"text": "Eindeutige Hashwerte", "correct": false, "because": "Kollisionen vermeiden"}, {"text": "Maximale Speichergröße", "correct": true, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist SHA-256 sicherer als MD5?', 2, '[{"text": "Ja", "correct": true, "because": "Stärkere Kollisionsresistenz"}, {"text": "Nein", "correct": false, "because": "MD5 veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Algorithmen sichern Integrität?', 4, '[{"text": "SHA-256", "correct": true, "because": "Starke Prüfsumme"}, {"text": "SHA-1", "correct": false, "because": "Weniger sicher"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Kein Algorithmus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Hashfunktionen auch verschlüsseln. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Integrität, keine Verschlüsselung"}, {"text": "Ja", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Hashfunktionen?', 3, '[{"text": "Kollisionsresistenz", "correct": true, "because": "Sichert Einzigartigkeit"}, {"text": "Schnelle Datenübertragung", "correct": false, "because": "Sekundär"}, {"text": "Grafisches Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Hashfunktionen erzeugen Prüfsummen. b) Sie sind für Verschlüsselung gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verschlüsselung ist separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Hashfunktionen?', 5, '[{"text": "Integritätsprüfung", "correct": true, "because": "Veränderungen erkennen"}, {"text": "Schnelle Berechnung", "correct": true, "because": "Effizient bei großen Daten"}, {"text": "Maximale Speicherung", "correct": false, "because": "Irrelevant"}, {"text": "Datenbankgröße", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Hashfunktionen unwichtig?', 3, '[{"text": "Einwegfunktion", "correct": false, "because": "Sichert Schutz"}, {"text": "Kollisionsresistenz", "correct": false, "because": "Vermeidet Dopplungen"}, {"text": "Schriftgröße", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Können Hashfunktionen Daten entschlüsseln?', 3, '[{"text": "Nein", "correct": true, "because": "Nicht umkehrbar"}, {"text": "Ja", "correct": false, "because": "Nur Prüfsummen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Hashfunktionen auch Authentizität sichern?', 2, '[{"text": "Ja", "correct": true, "because": "Mit HMAC möglich"}, {"text": "Nein", "correct": false, "because": "Erweiterte Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mittel wähle ich für Integritätssicherung?', 4, '[{"text": "SHA-256", "correct": true, "because": "Starke Prüfsumme"}, {"text": "Hohe Latenz", "correct": false, "because": "Irrelevant"}, {"text": "Großer Speicher", "correct": false, "because": "Kein Schutzfaktor"}]');
